from lib import *
S = SS('f164')
R = J('f164'); pl = R['plain']; rc = R['rich']; fl = R['flask']; sp = R['steps']
k = list(pl); kr = list(rc); kf = list(fl)
steps = [
    step(f"10000 行(每行 6 个字段)标准库 json 各选项:json.dumps 默认 {pl[k[0]]:.2f} ms;sort_keys=True {pl[k[1]]:.2f} ms(排序键多花约 {pl[k[1]] - pl[k[0]]:.1f} ms);ensure_ascii=False {pl[k[2]]:.2f} ms;紧凑 separators {pl[k[3]]:.2f} ms(耗时几乎不变,只是少几个字节);orjson.dumps {pl[k[4]]:.2f} ms,约 {pl[k[0]] / pl[k[4]]:.1f} 倍快;orjson 加排序键 {pl[k[5]]:.2f} ms。", b=bars([['json 默认', pl[k[0]], f'{pl[k[0]]:.1f} ms'], ['json sort_keys', pl[k[1]], f'{pl[k[1]]:.1f} ms'], ['orjson', pl[k[4]], f'{pl[k[4]]:.2f} ms']], pl[k[1]], mark=[1], done=[2]), t=tl(S(1)), done=lidx(S(1), 'orjson.dumps'), mark=lidx(S(1), 'sort_keys'), kv=KV([['json.dumps', f'{pl[k[0]]:.1f} ms'], ['sort_keys', f'+{pl[k[1]] - pl[k[0]]:.1f} ms'], ['orjson', f'{pl[k[4]]:.2f} ms']], ['orjson'])),
    step(f"含 datetime 与 Decimal 的 10000 行:标准库 json 要靠 default 钩子逐个转换(每行 2 个对象,共 20000 次 Python 函数调用),{rc[kr[0]]:.1f} ms;orjson 原生支持 datetime,Decimal 用 default 转成字符串,{rc[kr[1]]:.1f} ms,约 {rc[kr[0]] / rc[kr[1]]:.1f} 倍快。default 钩子是标准库慢下来的主要原因:每遇到一个不认识的对象就回调一次 Python。", b=bars([['json + default', rc[kr[0]], f'{rc[kr[0]]:.1f} ms'], ['orjson', rc[kr[1]], f'{rc[kr[1]]:.1f} ms']], rc[kr[0]], mark=[0], done=[1]), t=tl(S(2)), done=lidx(S(2), 'orjson'), mark=lidx(S(2), 'default 钩子被调用'), kv=KV([['标准库', f'{rc[kr[0]]:.1f} ms,20000 次 default 回调'], ['orjson', f'{rc[kr[1]]:.1f} ms']], ['标准库'])),
    step(f"Flask 里:视图返回 dict 或 jsonify 走 DefaultJSONProvider(sort_keys 默认 True,遇到 datetime 等走它的 default 函数)。默认 provider /plain {fl[kf[0]][0]:.1f} ms、/rich {fl[kf[0]][1]:.1f} ms;换成自己写的 orjson provider(继承 JSONProvider,实现 dumps、loads、response)后 /plain {fl[kf[1]][0]:.1f} ms、/rich {fl[kf[1]][1]:.1f} ms,响应大小都是 {fl[kf[0]][2] / 1e6:.2f} MB——注意 orjson provider 里没有 sort_keys,键的顺序是插入顺序,而不是排序后的(这会改变响应内容的字节顺序,对依赖响应排序的缓存与测试有影响)。", b=bars([['默认 /rich', fl[kf[0]][1], f'{fl[kf[0]][1]:.1f} ms'], ['orjson /rich', fl[kf[1]][1], f'{fl[kf[1]][1]:.1f} ms']], fl[kf[0]][1], mark=[0], done=[1]), t=tl(S(3)), done=lidx(S(3), 'orjson provider'), mark=lidx(S(3), '默认 provider'), kv=KV([['/plain', f'{fl[kf[0]][0]:.1f} → {fl[kf[1]][0]:.1f} ms'], ['/rich', f'{fl[kf[0]][1]:.1f} → {fl[kf[1]][1]:.1f} ms']], ['/rich'])),
    step(f"哪一步占大头:10000 个 dataclass 对象,dataclasses.asdict 转成 dict 要 {sp[0]:.1f} ms,手写字典推导只要 {sp[1]:.1f} ms,json.dumps 转 JSON 要 {sp[2]:.1f} ms;orjson 直接序列化 dataclass 对象 {sp[3]:.1f} ms,省掉了「对象转 dict」这一步。很多时候慢的不是 JSON 编码,而是 asdict 这类通用转换(它递归深拷贝)。", t=tl(S(4)), done=lidx(S(4), 'dataclasses.asdict'), kv=KV([['asdict', f'{sp[0]:.1f} ms'], ['手写字典', f'{sp[1]:.1f} ms'], ['orjson 直接序列化对象', f'{sp[3]:.1f} ms']], ['asdict'])),
]
A = mkartf('f164', 164, 'Flask,JSON,序列化,orjson,性能,真实验证,动画演示',
    f'实测 Flask 的 JSON 序列化性能:1 万行标准库 json 7.1 ms 对 orjson {pl[k[4]]:.2f} ms、sort_keys 的额外开销、含 datetime 与 Decimal 时 default 钩子让标准库慢到 {rc[kr[0]]:.1f} ms、Flask 默认 provider 对自写 orjson provider({fl[kf[0]][1]:.1f} 对 {fl[kf[1]][1]:.1f} ms)、dataclasses.asdict 比 json.dumps 还慢。',
    'Flask 返回 JSON 慢在哪?换 orjson 能快多少?datetime 与 Decimal 为什么会拖慢?sort_keys 与 asdict 的代价是什么?这篇把每一环量出来。',
    [(f'{pl[k[0]] / pl[k[4]]:.1f} 倍', '10000 行简单数据:orjson 相对标准库 json.dumps 的速度'), (f'{rc[kr[0]] / rc[kr[1]]:.1f} 倍', '含 datetime 与 Decimal 时 orjson 相对标准库加 default 钩子的速度'), (f'{sp[0]:.0f} ms', '对 10000 个 dataclass 做 asdict 的耗时,比 json.dumps 本身还慢')],
    [('标准库的各选项', '<p>上一篇:<a href="flask-template-render-time.html">模板渲染耗时</a>;下一篇:<a href="flask-gunicorn-worker-count.html">Gunicorn Worker 数量</a>。</p><p>第 117 篇从大响应的角度看过一次 orjson,这里把序列化各环节拆开比较。</p>'), ('datetime 与 Decimal', None), ('Flask 的 JSON provider', None), ('对象转 dict 的代价', None)],
    steps, [ENV_F + '。orjson 3.12.0', '没有验证:ujson、msgspec 等其它序列化库、pydantic 的 model_dump_json 与 marshmallow 的耗时比较(第 115、116 篇有各自的数字)、数字精度(浮点)的差异、orjson provider 的 loads 在请求解析上的效果'], 'JSON 序列化性能', panels=[('t', 'term', '实验输出'), ('b', 'bars', '耗时'), ('kv', 'kv', '要点')])
